const TRACKER_ANCHOR = 1794254779912;
async function waitForWindow() {
  const now = Date.now();
  const elapsed = now - TRACKER_ANCHOR;
  const windowPos = ((elapsed % 15000) + 15000) % 15000;
  const BURST_MS = 8000;
  // If starting now would straddle (windowPos + burst > 15000 - 300 buffer), wait to next window + 600ms
  if (windowPos + BURST_MS > 15000 - 400) {
    const waitMs = 15000 - windowPos + 600;
    console.log(`[script] window sync: pos ${windowPos}ms, waiting ${waitMs}ms for next window`);
    await new Promise(r => setTimeout(r, waitMs));
  } else {
    console.log(`[script] window sync: pos ${windowPos}ms, burst now`);
  }
}

