async function stunWait(bot, sdk, maxTicks = 30) {
  // Wait until we can act: no fresh stun messages
  for (let i = 0; i < maxTicks; i++) {
    const s = sdk.getState();
    if (!s) return;
    // If player is moving/walking path, keep waiting
    await sdk.waitForTicks(1);
    // break when no stun in last 2 ticks
    const recent = s.gameMessages.filter((m) => m.tick >= s.tick - 2 && /stunned|caught/i.test(m.text));
    if (recent.length === 0) return;
  }
}

