async function tryOpenGates(bot, sdk) {
  // Open any closed large doors nearby so pathing doesn't route the bot inside
  const s = sdk.getState();
  if (!s) return;
  const doors = s.nearbyLocs.filter((l) => /large door|door/i.test(l.name) && l.options.some((o) => /open/i.test(o)));
  for (const d of doors) {
    // only doors adjacent to player (0-2 tiles) matter
    if ((d.distance ?? 99) > 3) continue;
    try {
      const r = await bot.openDoor(d);
      console.log(`Open door ${d.x},${d.z}: ${r.success ? 'OK' : 'FAIL'} ${r.message}`);
      if (r.success) return;
    } catch (e) { console.log('openDoor err', e.message); }
  }
}

